import{_ as l,l as i,o as e,c as n,v as t,p as s,x as r,d as h,i as _,S as d}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"聚合物分子量与分布","description":"","frontmatter":{"title":"聚合物分子量与分布","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-polymer-mw.md","filePath":"litho/resist-polymer-mw.md","lastUpdated":1789023840000}'),p={name:"litho/resist-polymer-mw.md"};function m(c,a,P,E,u,A){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="聚合物分子量与分布" tabindex="-1">聚合物分子量与分布 <a class="header-anchor" href="#聚合物分子量与分布" aria-label="Permalink to &quot;聚合物分子量与分布&quot;">​</a></h1><div class="epigraph"><p>平均分子量定膜的内聚、溶解与 $T_g$；分布宽度定有没有一群短链先溶、一群长链留下毛边。一个 $M_w$ 不够签核。</p><footer>—— 据聚合物 Flory–Fox / 分子量分布通称；抗蚀剂溶解与 LER 叙述见 Mack</footer></div><p><a href="/litho/underlayer-adhesion">上一课</a>把失败分成界面剥与体内撕。缺口是体内：成膜聚合物的平均分子量与多分散性（PDI）。本课钉这两项，作为「从光子到轮廓」课序的收束。下一单元换成计数噪声，从<a href="/litho/acid-quencher-counting">酸与淬灭剂计数</a>起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>抗蚀剂树脂不是单一链长。\\(M_n\\)、\\(M_w\\) 与 \\(\\mathrm{PDI}=M_w/M_n\\) 决定：\\(T_g\\)（Flory–Fox 方向）、溶解速率对脱保护的敏感、显影时链是整根离开还是碎片脱落、膜的模量与倒塌。\\(M_w\\) 太低：暗侵蚀高、膜软、倒得早；\\(M_w\\) 太高：清底慢、残胶、内聚过强但溶解开关变钝。</p><p>缺口不是再写 \\(R(m)\\) 公式，而是：\\(R\\) 的参数来自一群链的统计。PDI 宽，短链在阈值以下就开始溶，肩变圆，\\(\\gamma\\) 看起来掉了；长链尾巴贡献颗粒感 LER。把 LWR 全部写成酸扩散，会漏掉这一截材料散粒。</p><h3 id="保护基分数不是分子量" tabindex="-1">保护基分数不是分子量 <a class="header-anchor" href="#保护基分数不是分子量" aria-label="Permalink to &quot;保护基分数不是分子量&quot;">​</a></h3><p>RD 的 \\(m\\) 是保护基还在的比例，沿同一根链可以不均匀。高分子量链要许多次脱保护才整根可溶，这是 Notch 形状的聚合物来源之一。换 \\(M_w\\) 等于换 Notch，不必换显影液。</p><p><span class="marginnote">GPC 测的是溶液里的分布，交联或团聚会撒谎。批次资格用同一套 GPC 方法，不要混用绝对光散射与相对聚苯乙烯标样还不声明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>资格：GPC 的 \\(M_n\\)、\\(M_w\\)、PDI，加上 \\(T_g\\)、\\(E_0\\)、暗侵蚀、LWR。实验：只换分子量批次、固定 PAG/碱，看衬度曲线肩部与高频 LER。与<a href="/litho/tg-free-volume">自由体积</a>联合：分子量升，\\(T_g\\) 升，\\(D\\) 往往降——PEB 核与溶解开关同时动，必须成套冻结。</p><p>金属氧化物胶的「分子量」换成团簇尺寸分布，统计角色类似，化学不同。本课默认有机树脂；MOR 随机课再换语言。</p>',12)),(e(),s(d,null,{default:r(()=>[_(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MN%5B%22Mn%20%2F%20Mw%22%5D%20--%3E%20TG%5B%22Tg%20%2F%20%E6%A8%A1%E9%87%8F%22%5D%0A%20%20PDI%5B%22PDI%22%5D%20--%3E%20R%5B%22R(m)%20%E8%82%A9%E9%83%A8%22%5D%0A%20%20PDI%20--%3E%20LER%5B%22%E9%93%BE%E5%B0%BA%E5%AF%B8%20LER%22%5D%0A%20%20TG%20--%3E%20D%5B%22%E9%85%B8%E6%89%A9%E6%95%A3%20D%22%5D%0A%20%20R%20--%3E%20GAMMA%5B%22%CE%B3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>显影是溶剂化链进入溶液。短链扩散快、所需极性翻转少，在争夺带暗侧先被挖走，边缘出现缺口；长链拖在亮侧，留下须状。酸扩散核把这些事件在空间上抹一层，但抹不掉链尺寸这一档的散粒——它会进后课 PSD 的中高频。倒塌：模量大致随 \\(M_w\\) 升，深宽比可以多活一点，代价是溶解。</p><p>PAG 加载很高时，小分子本身也增塑、并贡献另一套计数；树脂 \\(M_w\\) 的影响被稀释。配方是联合的，本课禁止只报「树脂 10k」而不报 PAG。</p><p><span class="marginnote">交联负胶把「分子量」在 PEB 里做大，分布被反应改写。正胶脱保护则是把有效可溶分子量降下来。极性相反，分布统计仍在。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某树脂 8 kDa 写成所有 ArF 层标准。不发明 GPC 谱图。平均场轮廓仿真用一个 \\(R(m)\\)，等于忽略 PDI；随机 MC 才会抽样链。下一单元从酸/碱分子计数开始，聚合物链是并列的离散源，本课只把分布当作那次抽样的材料前置。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(M_n\\)、\\(M_w\\)、PDI 改 \\(T_g\\)、溶解开关与链尺寸 LER。</li><li>Notch 与 \\(\\gamma\\) 的肩有一部分来自链长统计，不只来自 \\(R\\) 公式形状。</li><li>换分子量批次等于换核与换显影参数，要成套资格。</li><li>下一单元进入计数噪声，平均场到此收束。</li><li>出处：Flory–Fox 量级；Mack 对抗蚀剂溶解与聚合物的讨论。</li></ul>',8))])}const f=l(p,[["render",m]]);export{M as __pageData,f as default};
